BEGIN;
CREATE TABLE expenses.categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),sort_order bigint NOT NULL DEFAULT 0,archived_at timestamptz,created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),UNIQUE(household_id,name));
CREATE TABLE expenses.entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),occurred_on date NOT NULL,payee text NOT NULL DEFAULT '',description text NOT NULL CHECK(length(description) BETWEEN 1 AND 300),amount_minor bigint NOT NULL CHECK(amount_minor<>0 AND abs(amount_minor)<=1000000000000),kind text NOT NULL DEFAULT 'expense' CHECK(kind IN('expense','refund','reversal')),paid_by_membership_id uuid,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','posted')),reverses_entry_id uuid UNIQUE,replaces_entry_id uuid,posted_at timestamptz,created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),FOREIGN KEY(household_id,paid_by_membership_id) REFERENCES core.memberships(household_id,id),FOREIGN KEY(household_id,reverses_entry_id) REFERENCES expenses.entries(household_id,id),CHECK((kind='expense' AND amount_minor>0 AND reverses_entry_id IS NULL) OR (kind='refund' AND amount_minor<0 AND reverses_entry_id IS NULL) OR (kind='reversal' AND reverses_entry_id IS NOT NULL)),CHECK((state='posted')=(posted_at IS NOT NULL)));
CREATE TABLE expenses.entry_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),entry_id uuid NOT NULL,category_id uuid NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor<>0 AND abs(amount_minor)<=1000000000000),note text NOT NULL DEFAULT '',position integer NOT NULL DEFAULT 0,created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),FOREIGN KEY(household_id,entry_id) REFERENCES expenses.entries(household_id,id) ON DELETE CASCADE,FOREIGN KEY(household_id,category_id) REFERENCES expenses.categories(household_id,id));
CREATE INDEX entries_date ON expenses.entries(household_id,occurred_on DESC,id);
CREATE INDEX lines_entry ON expenses.entry_lines(household_id,entry_id);
CREATE FUNCTION expenses.protect_posted() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF current_user='household_owner' THEN IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF; IF TG_TABLE_NAME='entries' THEN IF OLD.state='posted' THEN RAISE EXCEPTION 'posted entry is immutable' USING ERRCODE='23514'; END IF; ELSE IF EXISTS(SELECT 1 FROM expenses.entries WHERE id=COALESCE(NEW.entry_id,OLD.entry_id) AND state='posted') THEN RAISE EXCEPTION 'posted allocation is immutable' USING ERRCODE='23514'; END IF; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER entries_immutable BEFORE UPDATE OR DELETE ON expenses.entries FOR EACH ROW EXECUTE FUNCTION expenses.protect_posted();
CREATE TRIGGER lines_immutable BEFORE INSERT OR UPDATE OR DELETE ON expenses.entry_lines FOR EACH ROW EXECUTE FUNCTION expenses.protect_posted();
CREATE FUNCTION expenses.validate_total() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE target uuid; expected bigint; actual numeric; status text; original bigint; BEGIN IF TG_TABLE_NAME='entries' THEN target=COALESCE(NEW.id,OLD.id); ELSE target=COALESCE(NEW.entry_id,OLD.entry_id); END IF; SELECT amount_minor,state INTO expected,status FROM expenses.entries WHERE id=target; IF status='posted' THEN SELECT coalesce(sum(amount_minor),0) INTO actual FROM expenses.entry_lines WHERE entry_id=target; IF actual<>expected THEN RAISE EXCEPTION 'allocation total mismatch' USING ERRCODE='23514'; END IF; IF EXISTS(SELECT 1 FROM expenses.entries WHERE id=target AND kind='reversal') THEN SELECT amount_minor INTO original FROM expenses.entries WHERE id=(SELECT reverses_entry_id FROM expenses.entries WHERE id=target); IF expected<>-original THEN RAISE EXCEPTION 'invalid reversal amount' USING ERRCODE='23514'; END IF; END IF; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER entries_total AFTER INSERT OR UPDATE ON expenses.entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION expenses.validate_total();
CREATE CONSTRAINT TRIGGER lines_total AFTER INSERT OR UPDATE OR DELETE ON expenses.entry_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION expenses.validate_total();
REVOKE EXECUTE ON FUNCTION expenses.protect_posted(),expenses.validate_total() FROM PUBLIC;
GRANT USAGE ON SCHEMA expenses TO household_app; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA expenses TO household_app;
COMMIT;
